def _tree_digest(root: Path) -> str | None:
    """Hash every regular file path and byte; reject links and special entries."""
    if root.is_symlink() or not root.is_dir():
        return None
    digest = hashlib.sha256()
    try:
        paths = sorted(root.rglob("*"), key=lambda path: path.as_posix())
        for path in paths:
            if path.is_symlink() or (not path.is_dir() and not path.is_file()):
                return None
            if path.is_file():
                digest.update(path.relative_to(root).as_posix().encode("utf-8") + b"\0")
                digest.update(path.read_bytes() + b"\0")
    except OSError:
        return None
    return digest.hexdigest()


def _reviewed_input_manifest() -> dict[str, str]:
    """Return the immutable reviewed mapping, rejecting a corrupt embedded blob."""
    try:
        raw = zlib.decompress(
            base64.b85decode(b"".join(_REVIEWED_INPUT_MANIFEST_B85.encode("ascii").split()))
        )
        decoded = json.loads(raw)
    except (ValueError, UnicodeDecodeError, zlib.error):
        return {}
    if not isinstance(decoded, dict) or not decoded:
        return {}
    if any(
        not isinstance(path, str)
        or not isinstance(digest, str)
        or len(digest) != 64
        or any(ch not in "0123456789abcdef" for ch in digest)
        for path, digest in decoded.items()
    ):
        return {}
    return decoded


# Keep this selector in lockstep with the manifest construction.  Everything it
# admits is content-bound, so an added/missing runtime module cannot silently
# change the renderer without invalidating reconciliation.  Other CI/release
# scripts are excluded deliberately: render only re-executes its own script and
# imports the production packages below, so pipeline-only edits are not inputs.
_RUNTIME_PYTHON_PREFIXES = (
    "agent/",
    "tools/",
    "nastech_cli/",
    "tui_gateway/",
    "gateway/",
    "plugins/",
    "cron/",
    "acp_adapter/",
    "nastech_platform/",
    "nastech_agent/",
    "optional-skills/",
    "providers/",
)
_EXPLICIT_RENDERER_INPUTS = frozenset(
    {
        "scripts/ci/prompt_surface.py",
        "pyproject.toml",
        "manifest.json",
        "toolsets.py",
        "toolset_distributions.py",
    }
)


def _is_renderer_input(rel: str) -> bool:
    return (
        rel.startswith(("skills/", "config/"))
        or rel in _EXPLICIT_RENDERER_INPUTS
        or ("/" not in rel and rel.endswith(".py"))
        or (rel.startswith(_RUNTIME_PYTHON_PREFIXES) and rel.endswith(".py"))
    )


def _record_renderer_input(root: Path, path: Path, actual: dict[str, str]) -> bool:
    """Hash one selected input, rejecting links and non-regular entries."""
    rel = path.relative_to(root).as_posix()
    if path.is_symlink() or not path.is_file():
        return False
    actual[rel] = hashlib.sha256(path.read_bytes()).hexdigest()
    return True


def actual_source_manifest(dst: str) -> dict[str, str] | None:
    """Derive the actual renderer-input path→SHA256 manifest from ``dst``.

    This is intentionally content based rather than Git/HEAD based; callers can
    audit or compare it without trusting an acquired checkout's provenance.
    Only renderer roots are traversed: a checkout's ``.git``, dependency trees,
    and virtual environments are neither renderer inputs nor useful work here.
    """
    root = Path(dst)
    if root.is_symlink() or not root.is_dir():
        return None
    actual: dict[str, str] = {}
    runtime_roots = tuple(prefix.removesuffix("/") for prefix in _RUNTIME_PYTHON_PREFIXES)
    complete_roots = ("skills", "config")
    try:
        # Top-level runtime modules and explicit renderer files are inputs; do
        # not walk unrelated top-level directories to find them.
        for path in root.iterdir():
            rel = path.relative_to(root).as_posix()
            if path.is_symlink():
                if _is_renderer_input(rel):
                    return None
                continue
            if path.is_dir():
                continue
            if _is_renderer_input(rel) and not _record_renderer_input(root, path, actual):
                return None

        # Skills and configuration are complete renderer roots, so every file
        # (and every symlink) in them is relevant.  Runtime roots only admit
        # Python files, but a symlinked root itself is always a rejected input.
        for name in complete_roots + runtime_roots:
            directory = root / name
            if not directory.exists() and not directory.is_symlink():
                continue
            if directory.is_symlink() or not directory.is_dir():
                return None
            for path in sorted(directory.rglob("*"), key=lambda item: item.as_posix()):
                rel = path.relative_to(root).as_posix()
                if path.is_symlink():
                    if _is_renderer_input(rel):
                        return None
                    continue
                if path.is_dir():
                    continue
                if not _is_renderer_input(rel):
                    continue
                if not _record_renderer_input(root, path, actual):
                    return None

        # The renderer script lives below an otherwise irrelevant scripts tree.
        # Inspect it directly rather than recursively visiting that tree.
        for rel in _EXPLICIT_RENDERER_INPUTS:
            if "/" not in rel:
                continue
            path = root / rel
            if not path.exists() and not path.is_symlink():
                continue
            if not _record_renderer_input(root, path, actual):
                return None
    except OSError:
        return None
    return actual


def source_matches_reviewed_manifest(dst: str) -> bool:
    """Check every actual renderer input, including additions and deletions."""
    expected = _reviewed_input_manifest()
    actual = actual_source_manifest(dst)
    return bool(expected) and actual == expected


def derive_source_fingerprint(dst: str) -> str | None:
    """Return a stable fingerprint of the actual reviewed input manifest.

    ``None`` means that the tree does not exactly match the reviewed renderer
    inputs.  Unlike a fork HEAD/tree argument, this value is derived from files
    actually present at the reconciliation destination.
    """
    actual = actual_source_manifest(dst)
    expected = _reviewed_input_manifest()
    if not expected or actual != expected:
        return None
    canonical = json.dumps(actual, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def _payload_files() -> dict[str, bytes] | None:
    """Decode the reviewed payload without writing it."""
    try:
        packed = zlib.decompress(base64.b85decode(b"".join(_PAYLOAD_B85.encode("ascii").split())))
        with tarfile.open(fileobj=io.BytesIO(packed), mode="r:") as archive:
            members = archive.getmembers()
            names = [member.name for member in members]
            if not members or len(set(names)) != len(names):
                return None
            files: dict[str, bytes] = {}
            for member in members:
                name = member.name
                pure = Path(name)
                if not member.isfile() or pure.is_absolute() or ".." in pure.parts:
                    return None
                source = archive.extractfile(member)
                if source is None:
                    return None
                files[name] = source.read()
            return files
    except (OSError, ValueError, tarfile.TarError, zlib.error):
        return None


def _snapshot_files(root: Path) -> dict[str, bytes] | None:
    if root.is_symlink() or not root.is_dir():
        return None
    files: dict[str, bytes] = {}
    try:
        for path in sorted(root.rglob("*"), key=lambda item: item.as_posix()):
            if path.is_symlink() or (not path.is_dir() and not path.is_file()):
                return None
            if path.is_file():
                files[path.relative_to(root).as_posix()] = path.read_bytes()
    except OSError:
        return None
    return files


def _unpack_reviewed(destination: Path) -> bool:
    """Extract only verified payload files and verify their complete tree."""
    files = _payload_files()
    if files is None:
        return False
    try:
        for name, content in files.items():
            target = destination / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(content)
    except OSError:
        return False
    return _tree_digest(destination) == REVIEWED_RENDERED_TREE


def _changed_snapshot_paths(before: dict[str, bytes], after: dict[str, bytes]) -> list[str]:
    """Account for each added, modified, and deleted snapshot file individually."""
    return [
        f"{SNAPSHOT_REL}/{rel}"
        for rel in sorted(before.keys() | after.keys())
        if before.get(rel) != after.get(rel)
    ]


def reconcile_prompt_surface(
    dst: str, *, source_fingerprint: str | None = None, unresolved: list[str] | None = None
) -> list[str]:
    """Replace exactly the reviewed stale tree with reviewed renderer output.

    ``source_fingerprint`` remains an optional compatibility argument but is not
    trusted as acquisition proof.  The actual destination's complete renderer
    input manifest is derived and compared before any snapshot mutation.
    """
    root = Path(dst)
    snapshot = root / SNAPSHOT_REL

    def conflict() -> list[str]:
        if unresolved is not None and SNAPSHOT_REL not in unresolved:
            unresolved.append(SNAPSHOT_REL)
        return []

    # Never let an unverified fork HEAD/tree stand in for current source bytes.
    if not source_matches_reviewed_manifest(dst):
        return conflict()
    before = _snapshot_files(snapshot)
    if before is None:
        return conflict()
    if _tree_digest(snapshot) == REVIEWED_RENDERED_TREE:
        return []
    if _tree_digest(snapshot) != REVIEWED_STALE_TREE:
        return conflict()
    after = _payload_files()
    if after is None:
        return conflict()
    changed = _changed_snapshot_paths(before, after)
    if not changed:
        return conflict()
    try:
        with tempfile.TemporaryDirectory(prefix="prompt-surface-", dir=root) as temp:
            staged = Path(temp) / "snapshot"
            staged.mkdir()
            if not _unpack_reviewed(staged):
                return conflict()
            backup = Path(temp) / "original"
            os.replace(snapshot, backup)
            try:
                os.replace(staged, snapshot)
            except OSError:
                os.replace(backup, snapshot)
                raise
    except OSError:
        return conflict()
    return changed
